// Browser pair calculation (apps/web/src/features/economy/) against the Python
// reference (aoe2x/economy/matchup.py). Expectations: tests/economy/fixtures/
// matchup-parity.json, regenerated by tools/economy/build_matchup_parity_fixture.py.
// Data: the committed artefact, shaped exactly like the published documents.
import test from 'node:test';
import assert from 'node:assert/strict';
import {createHash} from 'node:crypto';
import {readFileSync} from 'node:fs';
import {gunzipSync} from 'node:zlib';
import {createRuntimeData, evaluateMatchup} from '../../apps/web/src/features/economy/matchup.mjs';
import {createEconomyLoader, economyUrl} from '../../apps/web/src/features/economy/loader.mjs';
import {pySum} from '../../apps/web/src/features/economy/accounting.mjs';

const root = new URL('../../', import.meta.url);
const lines = gunzipSync(readFileSync(new URL('data/army_economics/army_context.jsonl.gz', root))).toString('utf8').split('\n');
const header = JSON.parse(lines[0]);
const metadataDocument = {civilizations: [], metadata: header.metadata};
const civilizationDocuments = lines.slice(1, -1).map(line => {
    const record = JSON.parse(line);
    metadataDocument.civilizations.push(record.civ);
    return {...record, contextVersion: header.metadata.contextVersion, schemaVersion: header.metadata.schemaVersion};
});
const fixture = JSON.parse(readFileSync(new URL('tests/economy/fixtures/matchup-parity.json', root)));

/** Same text as canonical() in tools/economy/build_matchup_parity_fixture.py. */
function canonical(value) {
    if (value === null) return 'null';
    if (typeof value === 'boolean') return String(value);
    if (typeof value === 'number') {
        if (!Number.isFinite(value)) throw new Error('non-finite number');
        return Object.is(value, -0) ? '-0' : String(value);
    }
    if (typeof value === 'string') return JSON.stringify(value).replace(/[\u007f-￿]/g, c => `\\u${c.charCodeAt(0).toString(16).padStart(4, '0')}`);
    if (Array.isArray(value)) return `[${value.map(canonical).join(',')}]`;
    return `{${Object.keys(value).sort().map(key => `${canonical(key)}:${canonical(value[key])}`).join(',')}}`;
}
const digest = value => createHash('sha256').update(canonical(value)).digest('hex');
const summary = result => ({
    labor: result.teams.map(t => t.investment.labor ? t.investment.labor.seconds : null),
    lowerTeam: result.investmentComparison.lowerTeam,
    production: result.teams.map(t => [t.production.id ?? null, t.production.buildingCount]),
});

test('the fixture was generated from the committed artefact', () => {
    assert.equal(fixture.header.contextVersion, header.metadata.contextVersion,
        'stale fixture: run python tools/economy/build_matchup_parity_fixture.py');
    assert.equal(fixture.cases.length, fixture.header.pairs);
    assert.ok(fixture.cases.length >= 2000);
});

test('every sampled pair equals the Python reference exactly (complete result)', () => {
    const data = createRuntimeData(metadataDocument, civilizationDocuments);
    const covered = {civs: new Set(), units: new Set(), mirrors: 0, errors: 0};
    const failures = [];
    for (const expected of fixture.cases) {
        const {left, right, populations} = expected;
        if (expected.error) {
            assert.throws(() => evaluateMatchup(data, left, right, populations), {message: expected.error});
            covered.errors += 1;
            continue;
        }
        const result = evaluateMatchup(data, left, right, populations);
        if (digest(result) !== expected.sha256) {
            failures.push({left, right, populations, js: summary(result), python: expected.summary});
            if (failures.length >= 5) break;
        }
        for (const side of [left, right]) { covered.civs.add(side[0]); covered.units.add(side.slice(0, 3).join('/')); }
        if (left.slice(0, 3).join('/') === right.slice(0, 3).join('/')) covered.mirrors += 1;
    }
    assert.deepEqual(failures, []);
    assert.equal(covered.civs.size, 56);
    assert.equal(covered.units.size, header.metadata.profileCount);
    assert.ok(covered.mirrors >= 100 && covered.errors >= 5);
});

test('pySum reproduces CPython 3.12+ compensated float summation', () => {
    assert.equal(pySum([]), 0);
    assert.equal(pySum([0.1, 0.2, 0.3]), 0.6);           // plain left-to-right gives 0.6000000000000001
    assert.equal(pySum([1e16, 1, -1e16]), 1);
    assert.ok(Object.is(pySum([-0]), 0));                 // int start 0 + -0.0 == 0.0
});

test('the loader reads the release file first and falls back to the API', async () => {
    const files = {metadata: {url: '/data/v/metadata.json'}, wu: {url: '/data/v/wu.json'}};
    assert.equal(economyUrl(files, null), '/data/v/metadata.json');
    assert.equal(economyUrl(files, 'Wu'), '/data/v/wu.json');
    assert.equal(economyUrl(files, 'Shu'), '/api/economy/Shu');
    assert.equal(economyUrl(null, null), '/api/economy');
    const documents = new Map([['/data/v/metadata.json', metadataDocument], ['/data/v/wu.json', civilizationDocuments.find(d => d.civ === 'Wu')],
        ['/api/economy/Shu', civilizationDocuments.find(d => d.civ === 'Shu')]]);
    const requests = [];
    let failNext = true;
    const fetch = async url => {
        requests.push(url);
        if (url === '/api/economy/Shu' && failNext) { failNext = false; return {ok: false, json: async () => ({})}; }
        return {ok: documents.has(url), json: async () => structuredClone(documents.get(url))};
    };
    const loader = createEconomyLoader({files, fetch});
    const wu = civilizationDocuments.find(d => d.civ === 'Wu').units[0], shu = civilizationDocuments.find(d => d.civ === 'Shu').units[0];
    await assert.rejects(loader.evaluate(['Wu', wu.unitId, wu.mode, 10], ['Shu', shu.unitId, shu.mode, 10]));
    const result = await loader.evaluate(['Wu', wu.unitId, wu.mode, 10], ['Shu', shu.unitId, shu.mode, 10]);
    const data = createRuntimeData(metadataDocument, civilizationDocuments);
    assert.equal(digest(result), digest(evaluateMatchup(data, ['Wu', wu.unitId, wu.mode, 10], ['Shu', shu.unitId, shu.mode, 10])));
    assert.deepEqual(requests.filter(url => url.endsWith('wu.json')), ['/data/v/wu.json']);  // cached
    assert.equal(requests.filter(url => url === '/api/economy/Shu').length, 2);           // failure retried
});

test('documents from another release are refused', () => {
    const stale = {...civilizationDocuments[0], contextVersion: '0'.repeat(64)};
    assert.throws(() => createRuntimeData(metadataDocument, [stale]), /another release/);
});
